// spec: specs/review-request-marking.md (1.1–1.3) · кейсы RM-01, RM-02, RM-03, RM-04, RM-05 · две роли: ребёнок QA-R2-1 (слот parent-r21-auto) → родитель (окно parent)
// seed: tests/seed.parent-r21-auto.spec.ts (ребёнок) / tests/seed.parent.spec.ts (родитель)
// Режим ребёнка — только в слоте parent-r21-auto (постоянно в режиме QA-R2-1, решение 08.11 #8ca267); parent.json в режим ребёнка НЕ переводится.
// Слот может быть ещё не в режиме ребёнка (первый прогон) или уже в нём — goChildHome справляется с обоими; в конце сессия слота сохраняется (saveSlot).
// Сценарий по порядку (пометка → вид у родителя → открытие запроса) → serial. Окна живут через все тесты файла.
// Предусловие: у QA-R2-1 на доме есть рекомендация, ещё не помеченная ребёнком (кнопка «לבקש בדיקה» активна).
// Если рекомендация уже помечена прошлым прогоном — тест остановится с понятной ошибкой (нужна свежая рекомендация).
// Данные: пометка ребёнка + feedback_review (открытый запрос) на каждый прогон → номер «בקשה #…» в annotations «cleanup»
// (закрыть в /reviews вручную, чтобы не копились открытые запросы).
// Не прогонять при записи — запуск только по /qa-regress.
import { BrowserContext, Page, Request } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openSharedUserPage } from '../placement-results/placement.helpers';
import { CHILD_SLOTS, goChildHome, openSlotPage, saveSlot } from '../child-slot.helpers';
import { T, openParentRecent, parentMarks, recentRows } from './review-request-marking.helpers';

const KID = CHILD_SLOTS['QA-R2-1'];

test.describe.configure({ mode: 'serial' });

test.describe('Пометка ребёнка «לבקש בדיקה» у родителя (autotest-writer, две роли)', () => {
  let kid: { context: BrowserContext; page: Page };
  let parent: { context: BrowserContext; page: Page };
  const writes: Request[] = [];
  let childMarksBefore = 0;
  let childMarksAfter = 0;
  let reviewMarksAfterMark = 0;

  test.beforeAll(async ({ browser }, testInfo) => {
    parent = await openSharedUserPage(browser, testInfo, 'parent');
    kid = await openSlotPage(browser, testInfo, KID);
    kid.page.on('request', (r) => {
      if (r.url().includes('/rest/v1/') && r.method() === 'POST') writes.push(r);
    });
  });

  test.afterAll(async () => {
    // refresh-токен Supabase одноразовый — сохранить сессию слота обратно
    await saveSlot(kid?.context, KID);
    await kid?.context.close();
    await parent?.context.close();
  });

  test('Ребёнок: «לבקש בדיקה» → «ההורה יראה את הבקשה…», кнопка выключена, запрос проверки не создаётся @desktop @data #37cdff', async () => {
    test.setTimeout(2 * 60_000);
    // Сколько пометок ребёнка у родителя до
    await openParentRecent(parent.page);
    childMarksBefore = await parentMarks(parent.page).child.count();

    // Дом ребёнка в слоте: передача (первый прогон) или закрыть гейт (слот уже в режиме ребёнка) → «למה זה הומלץ?»
    const page = kid.page;
    await goChildHome(page, KID);
    await page.getByRole('button', { name: T.childWhy }).or(page.getByRole('link', { name: T.childWhy })).filter({ visible: true }).first().click(); // TODO verify selector

    const ask = page.getByRole('button', { name: T.childAsk, exact: true }).filter({ visible: true }).first();
    await expect(ask).toBeVisible();
    await expect(ask, 'рекомендация уже помечена прошлым прогоном — нужна свежая рекомендация у QA-R2-1, остановиться и сообщить').toBeEnabled();

    writes.splice(0, writes.length);
    const responded = page.waitForResponse((r) => r.url().includes('/rest/v1/rpc/respond_recommendation'));
    await ask.click();
    expect((await responded).ok()).toBeTruthy();

    // RM-01: ребёнку сказано, что родитель увидит; повторно нажать нельзя
    await expect(page.getByText(T.childAsked).filter({ visible: true }).first()).toBeVisible();
    await expect(ask).toBeDisabled();
    // Тикет «מה קיים»: из режима ребёнка запрос проверки (feedback_reviews) не создаётся — его открывает родитель (решение 28.10, #73248f)
    const reviewWrites = writes.filter((r) => /feedback_review|request_[a-z_]*review/.test(r.url()));
    expect(reviewWrites.map((r) => r.url()), 'из режима ребёнка создан запрос проверки').toEqual([]);
  });

  test('Родитель: в «המלצות אחרונות» метка «הילד ביקש לבדוק», а не «בבדיקה»; на «למה זה הומלץ» — блок, пояснение и «פתיחת בקשת בדיקה» @desktop @data #37cdff', async () => {
    const page = parent.page;
    await page.reload();
    await expect(page.getByText(T.parentRecent).filter({ visible: true }).first()).toBeVisible();
    const marks = parentMarks(page);

    // RM-02 (тикет «מה רצוי» «ההורה רואה בבירור שהילד ביקש בדיקה»): пометок стало на одну больше
    await expect(marks.child).toHaveCount(childMarksBefore + 1);
    childMarksAfter = childMarksBefore + 1;
    reviewMarksAfterMark = await marks.review.count();
    // RM-05: ни одна строка с пометкой ребёнка не помечена «בבדיקה»
    const markedRows = recentRows(page).filter({ hasText: T.markChild });
    const n = await markedRows.count();
    for (let i = 0; i < n; i++) await expect(markedRows.nth(i)).not.toContainText(new RegExp(`(^|[•·]\\s*)${T.markReview}(\\s*[•·]|$)`));

    // RM-03: «למה זה הומלץ» этой рекомендации
    await markedRows.first().click();
    await expect(page.getByText(T.markChild).filter({ visible: true }).first()).toBeVisible();
    // Пояснение: запрос ещё не у команды (комментарий программиста 01.11). TODO verify selector: точный текст пояснения
    await expect(page.getByText(/עדיין לא|לא נשלחה|לא הועברה/).filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByRole('button', { name: T.openReview }).filter({ visible: true }).first()).toBeVisible();
  });

  test('Родитель: «פתיחת בקשת בדיקה» → форма предзаполнена «אחר / הילד ביקש לבדוק…» → «שליחת בקשה» → «בקשה #…», метка → «בבדיקה» @desktop @data #37cdff', async ({}, testInfo) => {
    const page = parent.page;
    await page.getByRole('button', { name: T.openReview }).filter({ visible: true }).first().click();

    // RM-04: предзаполнено — причина «אחר» выбрана, в тексте «הילד ביקש לבדוק»
    await expect(page.getByRole('radio', { name: T.otherReason }).filter({ visible: true }).first()).toHaveAttribute('aria-checked', 'true'); // TODO verify selector
    await expect(page.getByRole('textbox').filter({ visible: true }).first()).toHaveValue(/הילד ביקש לבדוק/);

    const created = page.waitForResponse((r) => r.url().includes('/rest/v1/') && r.request().method() === 'POST' && /review/.test(r.url()));
    await page.getByRole('button', { name: T.sendReview, exact: true }).filter({ visible: true }).first().click();
    expect((await created).ok()).toBeTruthy();
    const status = page.getByText(/בקשה #[0-9a-f]{8}/).filter({ visible: true }).first();
    await expect(status).toBeVisible();
    testInfo.annotations.push({
      type: 'cleanup',
      description: `feedback_review ${(await status.textContent())?.match(/#[0-9a-f]{8}/)?.[0]} (QA-R2-1, #37cdff) — закрыть в /reviews вручную`,
    });

    // Тикет «התווית «בבדיקה» מופיעה רק כשיש בקשת בדיקה אמיתית»: пометка ребёнка → «בבדיקה»
    await openParentRecent(page);
    const marks = parentMarks(page);
    await expect(marks.child).toHaveCount(childMarksAfter - 1);
    await expect(marks.review).toHaveCount(reviewMarksAfterMark + 1);
  });
});
